def tr(lang: str, key: str, **kw) -> str:
    entry = S.get(key) or {}
    text = entry.get(lang) or entry.get("fa") or key
    if kw:
        for k, v in kw.items():
            text = text.replace("{" + k + "}", str(v))
    return text


